# Reuse test points; mark 3 between zeros in each row/column
p=set(pts)
mark=set(p)
for r in range(27):
    cs=[c for rr,c in p if rr==r]
    if len(cs)>=2:
        mark.update((r,c) for c in range(min(cs),max(cs)+1))
for c in range(18):
    rs=[r for r,cc in p if cc==c]
    if len(rs)>=2:
        mark.update((r,c) for r in range(min(rs),max(rs)+1))
rows2=[[0 if (r,c) in p else (3 if (r,c) in mark else 9) for c in range(18)] for r in range(27)]
print('\n'.join(' '.join(map(str,x)) for x in rows2))

